import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.CyZTVJbV.js";const m=JSON.parse('{"title":"Fidelity — dogfood-multimodal-chat (v1.15-4)","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/ai-llm/multimodal-chat.md","filePath":"quality-reports/ai-llm/multimodal-chat.md"}'),o={name:"quality-reports/ai-llm/multimodal-chat.md"};function d(n,e,l,r,c,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="fidelity-—-dogfood-multimodal-chat-v1-15-4" tabindex="-1">Fidelity — dogfood-multimodal-chat (v1.15-4) <a class="header-anchor" href="#fidelity-—-dogfood-multimodal-chat-v1-15-4" aria-label="Permalink to &quot;Fidelity — dogfood-multimodal-chat (v1.15-4)&quot;">​</a></h1><p>Real-vs-mock behavioural fidelity for the Anthropic vision (multimodal) dogfood, produced by <code>examples/dogfood-multimodal-chat/tests/emit-fidelity-report.test.ts</code>. Feeds <code>@kiwa-test/quality-metrics</code> 11-axis release gate.</p><h2 id="baseline-real-mode-skipped-—-no-anthropic-api-key" tabindex="-1">Baseline (real mode skipped — no <code>ANTHROPIC_API_KEY</code>) <a class="header-anchor" href="#baseline-real-mode-skipped-—-no-anthropic-api-key" aria-label="Permalink to &quot;Baseline (real mode skipped — no \`ANTHROPIC_API_KEY\`)&quot;">​</a></h2><p>When the harness runs without an Anthropic API key, the real adapter emits <code>ANTHROPIC_ENV_MISSING</code> for every op. Divergences are recorded so the mock adapter is not spuriously credited with parity — the harness stays honest even in local dev.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>provider   : @kiwa-test/ai-llm/multimodal-chat</span></span>
<span class="line"><span>version    : 0.1.0</span></span>
<span class="line"><span>verdict    : FAIL (accuracy.score 0.30 vs threshold 0.80)</span></span>
<span class="line"><span>divergences: 3 (describeImage / streamDescribeImage / compareImages — real mode absent)</span></span>
<span class="line"><span>axes       : 11 (AI-LLM branch)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>axis</th><th>actual</th><th>threshold</th><th>verdict</th></tr></thead><tbody><tr><td>coverage.line</td><td>92.00%</td><td>85%</td><td>pass</td></tr><tr><td>coverage.branch</td><td>88.00%</td><td>80%</td><td>pass</td></tr><tr><td>coverage.function</td><td>95.00%</td><td>90%</td><td>pass</td></tr><tr><td>fidelity.ratio</td><td>100.00% (3/3)</td><td>70%</td><td>pass</td></tr><tr><td>perf.p95Ms</td><td>16.00 ms</td><td>100 ms</td><td>pass</td></tr><tr><td>mutation.killRate</td><td>70.00% (28/40)</td><td>60%</td><td>pass</td></tr><tr><td>testCount.behavior</td><td>12</td><td>10</td><td>pass</td></tr><tr><td>cost.perRequestUsd</td><td>$0.0049</td><td>$0.10</td><td>pass</td></tr><tr><td>latency.p95Ms</td><td>16.00 ms</td><td>3000 ms</td><td>pass</td></tr><tr><td>token.totalTokens</td><td>1541</td><td>4000</td><td>pass</td></tr><tr><td>accuracy.score</td><td>0.30</td><td>0.80</td><td><strong>fail</strong></td></tr></tbody></table><p>Accuracy is the mean Jaccard similarity between the real and mock text replies. In real-mode-skipped mode the &quot;real&quot; strings are seeded from expected Anthropic vision outputs so the harness has something to diff — the fail is by design and signals that fidelity is unverified without a live key. Wiring <code>ANTHROPIC_API_KEY</code> and running against <code>claude-3-5-sonnet-latest</code> promotes the report to the real baseline.</p><p>Vision requests are substantially heavier than text-only chat — the per-request token count (~1541) reflects the pre-flight image token cost (1200 tokens at <code>detail: auto</code> for a single image, 2400 for 2-image compare) plus the small text delta. Cost per request is ~15× the text-only baseline, matching the Anthropic pricing table for image content blocks.</p><h2 id="reproduction" tabindex="-1">Reproduction <a class="header-anchor" href="#reproduction" aria-label="Permalink to &quot;Reproduction&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood-multimodal-chat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/dogfood-multimodal-chat/quality-report/fidelity-latest.md</span></span></code></pre></div><p>Live real-mode.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ANTHROPIC_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sk-ant-...</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ANTHROPIC_MODEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">claude-3-5-sonnet-latest</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood-multimodal-chat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><h2 id="ops-under-measurement" tabindex="-1">Ops under measurement <a class="header-anchor" href="#ops-under-measurement" aria-label="Permalink to &quot;Ops under measurement&quot;">​</a></h2><p>Three provider-neutral vision ops on <code>VisionChatAdapter</code>.</p><ul><li><code>describeImage</code> — non-streaming vision call, 1 image + text prompt, optional system prompt + <code>detail</code> hint</li><li><code>streamDescribeImage</code> — streaming vision call, SSE <code>content_block_delta</code> chunks accumulated</li><li><code>compareImages</code> — multi-image call, N image blocks followed by the text prompt (drives the &quot;cost dominated by vision&quot; pattern)</li></ul><h2 id="image-token-accounting" tabindex="-1">Image token accounting <a class="header-anchor" href="#image-token-accounting" aria-label="Permalink to &quot;Image token accounting&quot;">​</a></h2><p>Each image contributes a base cost that scales with the <code>detail</code> hint (mirrors OpenAI vision&#39;s cost model so mock and real report the same <code>imageTokenEstimate</code> on the response object).</p><ul><li><code>detail: &#39;low&#39;</code> — 1500 × 0.5 = 750 tokens / image</li><li><code>detail: &#39;auto&#39;</code> (default) — 1500 × 0.8 = 1200 tokens / image</li><li><code>detail: &#39;high&#39;</code> — 1500 × 1 = 1500 tokens / image</li></ul><p>For a 2-image compare call at default detail, <code>imageTokenEstimate</code> = 2400 — the mock uses this figure to inflate <code>usage.input_tokens</code> so token / cost samples flow through the 4 AI-LLM axes with the correct order of magnitude.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>The mock&#39;s response bank in <code>examples/dogfood-multimodal-chat/src/adapters/mock.ts</code> keys by the trailing text block of the user message (the vision message concatenates image blocks + text, and the shared <code>MockEngine</code> matches on the text portion). Each response returns a Claude-shaped vision reply so streaming chunks + finish reason + usage all take realistic shapes.</p><p>Provider prefix <code>@kiwa-test/ai-llm/</code> triggers the 11-axis branch of <code>evaluateReleaseGate</code> (<code>packages/quality-metrics/src/gate.ts</code> — the 4 AI-LLM axes cost / latency / token / accuracy are added on top of the shared 7).</p><p>The real adapter (<code>src/adapters/real.ts</code>) speaks Anthropic&#39;s HTTP API directly — headers <code>x-api-key</code> + <code>anthropic-version: 2023-06-01</code>, body includes <code>image</code> content blocks whose <code>source</code> is either <code>{ type: &#39;base64&#39;, media_type, data }</code> or <code>{ type: &#39;url&#39;, url }</code>. No <code>@anthropic-ai/sdk</code> dependency is dragged into the workspace root; the shape stays honest.</p>`,23)])])}const u=t(o,[["render",d]]);export{m as __pageData,u as default};
